use std::error::Error;
use std::fmt::Write as _;
use std::io::Write as _;
use std::sync::mpsc;

use wgpu::util::DeviceExt;

/// One thread per grid point. Each thread runs the escape-time loop for its
/// point and writes the number of steps taken to `out`.
const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    dx: f32,
    y_min: f32,
    dy: f32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) {
        return;
    }
    let cx = p.x_min + (f32(id.x) + 0.5) * p.dx;
    let cy = p.y_min + (f32(id.y) + 0.5) * p.dy;

    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (n >= p.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    out[id.y * p.width + id.x] = n;
}
"#;

const WORKGROUP: u32 = 16;

/// Uniform block passed to the shader. Layout must match `struct Params`.
#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x_min: f32,
    dx: f32,
    y_min: f32,
    dy: f32,
}

struct Job {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_job(text: &str) -> Result<Job, Box<dyn Error>> {
    let tokens: Vec<&str> = text.split_whitespace().collect();
    if tokens.len() != 7 {
        return Err(format!("expected 7 numbers in job file, found {}", tokens.len()).into());
    }

    let width: u32 = tokens[0].parse()?;
    let height: u32 = tokens[1].parse()?;
    let limit: u32 = tokens[2].parse()?;
    let x_min: f64 = tokens[3].parse()?;
    let x_max: f64 = tokens[4].parse()?;
    let y_min: f64 = tokens[5].parse()?;
    let y_max: f64 = tokens[6].parse()?;

    if !(1..=1024).contains(&width) || !(1..=1024).contains(&height) {
        return Err("width and height must be between 1 and 1024".into());
    }
    if !(1..=1000).contains(&limit) {
        return Err("limit must be between 1 and 1000".into());
    }
    if !(x_min.is_finite() && x_max.is_finite() && y_min.is_finite() && y_max.is_finite()) {
        return Err("bounds must be finite".into());
    }
    if x_min >= x_max || y_min >= y_max {
        return Err("require x_min < x_max and y_min < y_max".into());
    }

    Ok(Job {
        width,
        height,
        limit,
        x_min,
        x_max,
        y_min,
        y_max,
    })
}

/// Runs the escape-time kernel and returns one escape time per grid point,
/// row-major (index = row * width + column).
async fn escape_times_gpu(job: &Job) -> Result<Vec<u32>, Box<dyn Error>> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::default());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .map_err(|e| format!("no GPU adapter available: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot create GPU device: {e}"))?;

    // Pixel size computed in double precision, then narrowed for the GPU.
    let dx = (job.x_max - job.x_min) / f64::from(job.width);
    let dy = (job.y_max - job.y_min) / f64::from(job.height);
    let params = Params {
        width: job.width,
        height: job.height,
        limit: job.limit,
        pad: 0,
        x_min: job.x_min as f32,
        dx: dx as f32,
        y_min: job.y_min as f32,
        dy: dy as f32,
    };

    let uniform = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let count = u64::from(job.width) * u64::from(job.height);
    let size = count * std::mem::size_of::<u32>() as u64;
    let out = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("escape_times"),
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("escape"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("escape"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("escape"),
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: uniform.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: out.as_entire_binding(),
            },
        ],
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("escape"),
    });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("escape"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(
            job.width.div_ceil(WORKGROUP),
            job.height.div_ceil(WORKGROUP),
            1,
        );
    }
    encoder.copy_buffer_to_buffer(&out, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let (tx, rx) = mpsc::channel();
    readback.slice(..).map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device.poll(wgpu::PollType::wait_indefinitely())?;
    rx.recv()??;

    let data = readback.slice(..).get_mapped_range();
    let times: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(times)
}

/// Builds the ten output lines from the escape times.
fn summarize(times: &[u32], limit: u32) -> String {
    let mut inside: u64 = 0;
    let mut bins = [0u64; 8];
    let mut escaped: u64 = 0;
    let mut sum: u64 = 0;

    for &n in times {
        if n >= limit {
            inside += 1;
        } else {
            escaped += 1;
            sum += u64::from(n);
            // n < limit, so 8 * n / limit is at most 7.
            let bin = (8 * u64::from(n) / u64::from(limit)) as usize;
            bins[bin] += 1;
        }
    }

    let mean = if escaped == 0 {
        0.0
    } else {
        sum as f64 / escaped as f64
    };

    let mut out = String::new();
    let _ = writeln!(out, "INSIDE {inside}");
    for (i, count) in bins.iter().enumerate() {
        let _ = writeln!(out, "BIN {i} {count}");
    }
    let _ = writeln!(out, "MEAN {mean:.3}");
    out
}

fn run() -> Result<(), Box<dyn Error>> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: escape_times <job-file>")?;
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("cannot read {path}: {e}"))?;
    let job = parse_job(&text)?;

    let times = pollster::block_on(escape_times_gpu(&job))?;
    let report = summarize(&times, job.limit);

    let mut stdout = std::io::stdout().lock();
    stdout.write_all(report.as_bytes())?;
    stdout.flush()?;
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

